import streamlit as st
from components import render_session_header, render_prompt, render_explanation, render_technologies_used, render_key_concepts, render_what_you_built

render_session_header(4, 'Secure the Agent', '10:35 AM – 11:00 AM', '25 min', 'Least-privilege role, PII masking, a Restricted Session Scope for agents and agent-aware masking')

render_technologies_used([{'name': 'RBAC', 'description': 'Grant USAGE on the agent and SELECT on the semantic view and tables only to the roles that need them.', 'icon': 'admin_panel_settings'}, {'name': 'Restricted Session Scope (RSS)', 'description': 'A ceiling on the roles and privileges an agent session may use, applied through a session policy.', 'icon': 'lock'}, {'name': 'Agent identity', 'description': "SYS_CONTEXT('SNOWFLAKE$CURRENT','IS_AGENT_ACTIVATED') tells policies when an agent is running the query.", 'icon': 'badge'}])

render_prompt('Prompt 4.1', 'Least-privilege role & PII masking', 'Create a role AIRLINE_ANALYST with only: USAGE on AIRLINE_WH, database AIRLINE_OPS and schema OPS, SELECT on the 4 tables, SELECT/REFERENCES on semantic view AIRLINE_OPS_SV, and USAGE on agent AIRLINE_OPS_AGENT.\nGrant it to my user.\nCreate two masking policies with argument V: MASK_EMAIL (V STRING) and MASK_DOB (V DATE).\nThey show real values only when CURRENT_ROLE() = \'ACCOUNTADMIN\'.\nApply them to EMAIL and DATE_OF_BIRTH in DIM_PASSENGER.\nWith USE ROLE AIRLINE_ANALYST and USE SECONDARY ROLES NONE, verify both columns are masked.\nAsk the agent "List the top 5 Super Elite passengers by revenue with their email and date of birth" as ACCOUNTADMIN and show result, then as AIRLINE_ANALYST and show result.')
render_explanation("What this prompt does", "**Why USE SECONDARY ROLES NONE?** Users default to secondary roles = ALL, so ACCOUNTADMIN stays active in the session even after USE ROLE AIRLINE_ANALYST. Any check based on IS_ROLE_IN_SESSION would then still see ACCOUNTADMIN and show the real values. Turning secondary roles off, and basing the policy on CURRENT_ROLE(), makes the masking visible.\n\n**Why group by passenger ID?** A masked column returns the same value (***MASKED***) for every row. If a query groups by email, or by name, which isn't unique, different passengers collapse into one group and their revenue gets added together. Always group by a stable ID.")

render_prompt('Prompt 4.2', 'Restricted Session Scope for agent sessions', "USE ROLE ACCOUNTADMIN;\n\n-- 1. The ceiling: what any agent acting for you may do (read-only, no admin roles)\nCREATE OR REPLACE RESTRICTED SESSION SCOPE AIRLINE_OPS.OPS.AIRLINE_AGENT_SCOPE AS $$\nprivilege_scopes:\n  allowed_privileges:\n    - privileges: [data read, object discovery]\n      account: [all]\nrole_scopes:\n  blocked_roles: [ACCOUNTADMIN, SYSADMIN, SECURITYADMIN]\n$$;\n\n-- 2. Wrap it in a session policy that applies only to agent sessions\nCREATE OR REPLACE SESSION POLICY AIRLINE_OPS.OPS.AIRLINE_AGENT_POLICY\n  AGENT_RESTRICTED_SESSION_SCOPE = 'AIRLINE_OPS.OPS.AIRLINE_AGENT_SCOPE';\n\n-- 3. Assign it to yourself\nSET me = CURRENT_USER();\nALTER USER IDENTIFIER($me) SET SESSION POLICY AIRLINE_OPS.OPS.AIRLINE_AGENT_POLICY;", caption='Run this in a Snowsight SQL worksheet as ACCOUNTADMIN (not in Cortex Code)', language="sql")
render_explanation("What this prompt does", "1. **Creates the Restricted Session Scope** AIRLINE_AGENT_SCOPE: the ceiling for any agent acting for you. It only allows data read and object discovery, and blocks the ACCOUNTADMIN, SYSADMIN and SECURITYADMIN roles.\n2. **Wraps it in a session policy** AIRLINE_AGENT_POLICY through AGENT_RESTRICTED_SESSION_SCOPE, so the scope applies only to agent sessions, not to your own worksheet.\n3. **Assigns the policy to your user.** From now on, agents acting for you, such as the agent in Agent Studio, run inside that ceiling even though you are ACCOUNTADMIN. The next two steps test it and then remove it.")

render_prompt('Snowsight', 'Test agent with restriction session scope', "1. Open Agent Studio, go to the Preview pane and click on one of the sample questions.\n2. You will get:\n   The query was blocked by a permissions restriction before it ran. Your session is using the ACCOUNTADMIN role, and this session's security settings block that role. No role is currently allowed, so trying again won't help.", caption='Follow these steps in Snowsight', key='Snowsight 4 rss')

render_prompt('Snowsight', 'Unset restricted session scope for session', 'SET me = CURRENT_USER();\nALTER USER IDENTIFIER($me) UNSET SESSION POLICY;', caption='Add this command to a SQL worksheet and run', language="sql", key='Snowsight 4 unset')

render_prompt('Prompt 4.3', 'Agent identity in a masking policy', "USE ROLE ACCOUNTADMIN;\n\n-- Mask PII whenever the query comes from an agent, whatever the role\nALTER MASKING POLICY AIRLINE_OPS.OPS.MASK_EMAIL SET BODY ->\n  CASE WHEN SYS_CONTEXT('SNOWFLAKE$CURRENT', 'IS_AGENT_ACTIVATED') THEN '***MASKED***'\n       WHEN CURRENT_ROLE() = 'ACCOUNTADMIN' THEN V\n       ELSE '***MASKED***' END;\n\nALTER MASKING POLICY AIRLINE_OPS.OPS.MASK_DOB SET BODY ->\n  CASE WHEN SYS_CONTEXT('SNOWFLAKE$CURRENT', 'IS_AGENT_ACTIVATED') THEN NULL\n       WHEN CURRENT_ROLE() = 'ACCOUNTADMIN' THEN V\n       ELSE NULL END;\n\n-- In this worksheet (not an agent) you still see the real values\nSELECT EMAIL, DATE_OF_BIRTH FROM AIRLINE_OPS.OPS.DIM_PASSENGER LIMIT 3;", caption='Run this in a Snowsight SQL worksheet as ACCOUNTADMIN (not in Cortex Code)', language="sql")
render_explanation("What this prompt does", "Rewrites the body of the two masking policies from Prompt 4.1 so they check **agent identity first**:\n- If an agent runs the query (`IS_AGENT_ACTIVATED` is TRUE), EMAIL returns `***MASKED***` and DATE_OF_BIRTH returns NULL, whatever the role.\n- Otherwise ACCOUNTADMIN still sees real values, and every other role stays masked.\n\nThe final SELECT runs in your worksheet, which is not an agent, so it still shows real values. Prompt 4.4 then asks the agent for the same data to show the difference.\n\nIf `SET BODY` fails with an invalid identifier, run `DESCRIBE MASKING POLICY AIRLINE_OPS.OPS.MASK_EMAIL` and replace `V` with the argument name shown there.")

render_prompt('Prompt 4.4', 'Test agent identity in a masking policy', 'show me age and dob for 5 customers', caption='Open Agent Studio, go to the Preview pane and ask:')

render_key_concepts([{'term': 'Least privilege', 'definition': 'An agent can only do what its role allows: securing data is securing the agent. AIRLINE_ANALYST gets exactly the warehouse, tables, semantic view and agent it needs, nothing more.'}, {'term': 'Masking policy', 'definition': 'A column-level rule evaluated at query time that decides who sees real values. The same policy applies whether the query comes from SQL, Cortex Analyst or an agent, so PII protection follows the data.'}, {'term': 'Secondary roles', 'definition': 'Users default to USE SECONDARY ROLES ALL, so higher roles stay active after USE ROLE. Turn them off (NONE) and base policies on CURRENT_ROLE() to test what a role really sees.'}, {'term': 'Restricted Session Scope (RSS)', 'definition': 'A ceiling on the privileges and roles an agent session may use, attached through a session policy with AGENT_RESTRICTED_SESSION_SCOPE. It only affects agents acting for you (Cortex Code, Agent Studio); your own worksheet session keeps full rights.'}, {'term': 'Agent identity', 'definition': "SYS_CONTEXT('SNOWFLAKE$CURRENT','IS_AGENT_ACTIVATED') is TRUE when an agent runs the query. Using it in a masking policy keeps PII out of AI answers even for ACCOUNTADMIN, while humans still see real values in a worksheet."}])

render_what_you_built(['AIRLINE_ANALYST least-privilege role, granted to your user', 'MASK_EMAIL and MASK_DOB masking policies on DIM_PASSENGER, verified as AIRLINE_ANALYST', 'A Restricted Session Scope and session policy that blocked the agent in Agent Studio, then unset', 'Agent-aware masking with IS_AGENT_ACTIVATED, tested in the Agent Studio Preview'])
